public Map<String, Object> uploadZip(String str, MultipartFile multipartFile, boolean z) {
    if (multipartFile == null || multipartFile.isEmpty()) {
        return HttpResult.onError("file required");
    }
    String filename = multipartFile.getFilename();
    if (TextUtils.isEmpty(filename) || !filename.toLowerCase().endsWith(".zip")) {
        return HttpResult.onError("zip required");
    }
    if (multipartFile.getSize() > MAX_ZIP_SIZE) {
        return HttpResult.onError("zip max 50MB");
    }
    File externalFilesDir = AppContext.context.getExternalFilesDir(null);
    if (str != null && !str.isEmpty()) {
        externalFilesDir = new File(externalFilesDir, File.separator + str);
    }
    if (z && externalFilesDir.exists() && !deleteDirFiles(externalFilesDir)) {
        return HttpResult.onError("clear history file fail");
    }
    if (!externalFilesDir.exists() && !externalFilesDir.mkdirs()) {
        return HttpResult.onError("create subdir fail");
    }
    try {
        int iUnzipWithStructure = unzipWithStructure(multipartFile.getStream(), externalFilesDir);
        onUpdateProfile();
        return HttpResult.onSuccess(Integer.valueOf(iUnzipWithStructure));
    } catch (IOException e) {
        e.printStackTrace();
        return HttpResult.onError("unzipExtra ex:" + e.getMessage());
    }
}
